      {!day && who === 'rohan' && <div style={{position: 'absolute', left: 150, top: 160, width: 600, height: 420, background: `radial-gradient(ellipse at 50% 85%, rgba(140,170,255,${0.32 + 0.04 * Math.sin(f / 5)}), rgba(0,0,0,0) 70%)`}} />}
